import {simulate,clock,status,delay,reason,END} from './sim.mjs';
let t=0,conflict=30,playing=false,speed=5,selected='US',filter='all',last=performance.now();let s;
const $=id=>document.getElementById(id);const btn=(label,id,cls='')=>`<button class="token ${cls} ${selected===id?'selected':''}" data-entity="${id}" title="Inspect ${label}" aria-label="Inspect ${label}">${label}</button>`;
function patient(c){return btn(`P-${c.id}`,c.id)}
function caseForRoom(n){return s.cases.find(c=>c.room===n&&c.start!==null&&t<c.end)||s.cases.find(c=>c.room===n&&c.start===null&&t>=c.plan)}
function teamLocation(n){const c=caseForRoom(n);return c?`OR ${n}`:`OR ${n} · available`}
function render(){s=simulate(conflict,t);$('clock').textContent=clock(t);$('scrub').value=t;$('runstate').textContent=playing?'Running':'Paused';$('play').textContent=playing?'Pause':'Play';$('duration').textContent=`${conflict} min`;$('conflict').value=conflict;$('asof').textContent=`As of ${clock(t)}`;
const late=s.cases.filter(c=>delay(c,t)>0);$('late').textContent=late.length;$('minutes').innerHTML=late.reduce((a,c)=>a+delay(c,t),0)+'<span> min</span>';
let map='';for(let n=1;n<=3;n++){const c=caseForRoom(n);const st=c?status(c,t):'Available';map+=`<div class="room ${st==='In case'?'active':st==='Waiting'?'wait':''} ${selected===`OR${n}`?'selected':''}" role="button" tabindex="0" data-entity="OR${n}" aria-label="Inspect OR ${n}"><div class="room-header"><b>OR ${String(n).padStart(2,'0')}</b><span class="state-tag">${st}</span></div><div class="room-desc">${c?`Case ${c.id} · ${st==='Waiting'?reason(c,s).includes('US-01')?'Ultrasound unavailable':'Room / team unavailable':`started ${clock(c.start)}`}`:s.cases.some(c=>c.room===n&&c.end!==null&&t>=c.end&&c.ready===null)?'Room turnover · 15 min':'Dedicated team ready'}</div><div class="tokens">${c&&st==='In case'?patient(c):''}${['S','N','A'].map(role=>btn(`${role}${n}`,`${role}${n}`,'staff')).join('')}${s.machine.location===`OR ${n}`?btn('US-01','US','asset'):''}</div></div>`}
map+='<div class="hall">CONNECTING CORRIDOR · SCHEMATIC, NOT TO SCALE</div>';
map+=`<div class="room zone" role="button" tabindex="0" data-entity="PRE"><div class="room-header"><b>Pre-op</b><span class="state-tag">${s.cases.filter(c=>c.arrived&&c.start===null).length} patients</span></div><div class="tokens">${s.cases.filter(c=>c.arrived&&c.start===null).map(patient).join('')||'<span class="room-desc">No patients waiting</span>'}</div></div>`;
map+=`<div class="room zone" role="button" tabindex="0" data-entity="HUB"><div class="room-header"><b>Equipment hub</b></div><div class="tokens">${s.machine.location==='Equipment hub'?btn('US-01','US','asset'):'<span class="room-desc">US-01 is in a room</span>'}</div></div>`;
map+=`<div class="room zone" role="button" tabindex="0" data-entity="REC"><div class="room-header"><b>Recovery</b><span class="state-tag">${s.cases.filter(c=>c.end!==null&&t>=c.end&&c.discharge===null).length} patients</span></div><div class="tokens">${s.cases.filter(c=>c.end!==null&&t>=c.end&&c.discharge===null).map(patient).join('')||'<span class="room-desc">No patients recovering</span>'}</div></div>`;$('map').innerHTML=map;
$('schedule').innerHTML=`<div class="axis"><span></span><div class="ticks">${Array.from({length:8},(_,i)=>`<span>${clock(i*30)}</span>`).join('')}</div></div>`+s.cases.map(c=>{const d=delay(c,t);return `<div class="timeline-row"><button class="case-label" data-entity="${c.id}">Case ${c.id}<small>OR ${c.room} ${d?`· +${d}m`:''}</small></button><div class="track"><span class="bar plan" style="left:${c.plan/END*100}%;width:${c.duration/END*100}%" title="Planned ${clock(c.plan)}–${clock(c.plan+c.duration)}"></span>${d?`<span class="bar delay" style="left:${c.plan/END*100}%;width:${d/END*100}%" title="Observed start delay ${d} minutes"></span>`:''}${c.start!==null&&t>c.start?`<span class="bar actual" style="left:${c.start/END*100}%;width:${(Math.min(t,c.end)-c.start)/END*100}%" title="Actual start ${clock(c.start)}; ${status(c,t)}"></span>`:''}<span class="now-line" style="left:${t/END*100}%"></span></div></div>`}).join('');
renderInspector();let events=s.events.filter(e=>filter==='delay'?e.kind==='delay':filter==='selected'?matches(e.entity):true).slice().reverse();$('events').innerHTML=events.map(e=>`<div class="event ${e.kind==='delay'?'delayed':''}"><time>${clock(e.time)}</time><button data-entity="${e.entity}">${e.entity==='US'?'US-01':`Case ${e.entity}`}</button><span>${e.text}</span></div>`).join('')||'<div class="empty">No matching events at this time.</div>';
}
function matches(id){if(selected===id)return true;if(selected.startsWith('OR'))return s.cases.some(c=>c.id===id&&c.room===+selected.slice(2));if(/^[SNA][123]$/.test(selected))return s.cases.some(c=>c.id===id&&c.room===+selected.slice(1));return false}
function renderInspector(){let title,desc,facts=[],dep='';const c=s.cases.find(c=>c.id===selected);
if(c){title=`Patient P-${c.id} / Case ${c.id}`;desc=status(c,t);facts=[['Location',!c.arrived?'Outside suite':c.start===null?'Pre-op':t<c.end?`OR ${c.room}`:c.discharge===null?'Recovery':'Departed'],['Planned start',clock(c.plan)],['Actual start',c.start===null?'Not started':clock(c.start)],['Start delay',`${delay(c,t)} min`],['Required',`OR ${c.room} · S${c.room}, N${c.room}, A${c.room}${c.us?' · US-01':''}`]];dep=c.start===null?reason(c,s):c.prior?`Case ${c.prior} → room turnover (15 min) → OR ${c.room} and team → case ${c.id}`:`US-01 → case ${c.id} → room turnover (15 min) → case ${{A:'D',B:'E',C:'F'}[c.id]}`}
else if(selected==='US'){title='US-01';desc='Shared ultrasound machine';facts=[['Location',s.machine.location],['State',s.machine.status],['Assigned to',s.machine.owner?`Case ${s.machine.owner}`:'None'],['Extra hold',`${conflict} min · synthetic`],['Turnaround','5 min · fixed']];dep=`US-01 → case A → case B → case C. Each case requires exclusive use to start. ${s.machine.status==='Cleaning / transfer'?'Currently unavailable during turnaround.':''}`}
else if(/^[SNA][123]$/.test(selected)){const n=+selected.slice(1),roles={S:'Surgeon',N:'Nurse',A:'Anesthesia staff'};title=`${selected} · ${roles[selected[0]]}`;desc='Synthetic dedicated team member';const current=caseForRoom(n);facts=[['Location',teamLocation(n)],['State',current?status(current,t)==='Waiting'?'Waiting with assigned room':'In case':'Available / turnover'],['Assigned cases',s.cases.filter(c=>c.room===n).map(c=>c.id).join(', ')]];dep=`OR ${n} and its dedicated team remain unavailable until the current case ends and 15-minute turnover completes.`}
else if(selected.startsWith('OR')){const n=+selected.slice(2),c=caseForRoom(n);title=`Operating room ${n}`;desc=c?`Case ${c.id} · ${status(c,t)}`:'No case running';facts=[['Team',`S${n} · N${n} · A${n}`],['Cases',s.cases.filter(c=>c.room===n).map(c=>c.id).join(' → ')],['Turnover','15 min after each case']];dep=c?reason(c,s):'The next case needs its patient, room, dedicated team and any required equipment.'}
else{title=selected==='PRE'?'Pre-op':selected==='REC'?'Recovery':'Equipment hub';desc='Synthetic floor zone';facts=[['Capacity','Unconstrained in v0.1'],['Purpose',selected==='PRE'?'Wait for case start':selected==='REC'?'30-minute recovery':'Hold available equipment']];dep='Locations show discrete workflow transitions; walking paths and sensor accuracy are not modeled.'}
$('inspector').innerHTML=`<h2>${title}</h2><p>${desc}</p><dl class="facts">${facts.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><div class="dependency">${dep}</div>`}
function pause(){playing=false;last=performance.now()}
document.addEventListener('click',e=>{const el=e.target.closest('[data-entity]');if(el){selected=el.dataset.entity;render()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role=button]')){e.preventDefault();selected=e.target.dataset.entity;render()}});
$('play').onclick=()=>{if(t>=END)t=0;playing=!playing;last=performance.now();render()};$('reset').onclick=()=>{pause();t=0;conflict=30;selected='US';filter='all';$('filter').value=filter;speed=5;$('speed').value=5;render()};$('rewind').onclick=()=>{pause();t=Math.max(0,t-10);render()};$('next').onclick=()=>{pause();t=simulate(conflict,END).events.find(e=>e.time>t)?.time??END;render()};$('scrub').oninput=e=>{pause();t=+e.target.value;render()};$('speed').onchange=e=>speed=+e.target.value;$('conflict').oninput=e=>{pause();conflict=+e.target.value;render()};$('jump').onclick=()=>{pause();t=20;render()};$('filter').onchange=e=>{filter=e.target.value;render()};$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
setInterval(()=>{const now=performance.now();if(playing&&now-last>=1000/speed){const step=Math.floor((now-last)*speed/1000);t=Math.min(END,t+step);last=now;if(t===END)playing=false;render()}},60);render();
